function addInscription(parent){
 // 원 좌대의 세로 한자. 기존 간판과 같은 브라우저 글자 렌더링.
 const canvas=document.createElement('canvas');canvas.width=160;canvas.height=1280;
 const ctx=canvas.getContext('2d');ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='105px "Batang", "바탕", serif';
 const text='忠武公李舜臣將軍像';
 for(let i=0;i<text.length;i++){
  const y=100+i*133;ctx.fillStyle='#53544a';ctx.fillText(text[i],82,y+2);ctx.fillStyle='#b2a572';ctx.fillText(text[i],80,y);
 }
 const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;
 const label=new T.Mesh(new T.PlaneGeometry(.42,4.55),new T.MeshBasicMaterial({map:texture,transparent:true,depthWrite:false,alphaTest:.3}));
 label.name='original-vertical-inscription';label.position.set(0,5.08,1.142);label.rotation.x=-.0141;parent.add(label);
}
