   for(const id of new Set(source.array))if(id){const b=owner.userData.treeCanopies[id-1];ids.set(id,record(owner.uuid+':'+id,new T.Box3(new T.Vector3(...b.min),new T.Vector3(...b.max)).applyMatrix4(transform)));}
