  shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\\nuniform float waterTime;varying float vFlow;').replace('#include <color_fragment>','#include <color_fragment>\\ndiffuseColor.a*=.30+.70*pow(.5+.5*sin(vFlow*95.-waterTime*16.),2.);');
