 const perJet=18,positions=new Float32Array(jets.length*perJet*3),geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(positions,3).setUsage(T.DynamicDrawUsage));
 const dropsMaterial=new T.PointsMaterial({color:'#e4f1eb',size:site.radius>2?.09:.07,transparent:true,opacity:.76,depthWrite:false,sizeAttenuation:true});
 dropsMaterial.onBeforeCompile=shader=>{shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\\nfloat d=length(gl_PointCoord-vec2(.5));if(d>.5)discard;diffuseColor.a*=1.-smoothstep(.12,.5,d);');};
