 const splashGeometry=new T.BufferGeometry(),splashPositions=new Float32Array(jets.length*4*3);splashGeometry.setAttribute('position',new T.BufferAttribute(splashPositions,3).setUsage(T.DynamicDrawUsage));
 const splash=new T.Points(splashGeometry,dropsMaterial);splash.name='water-splash';group.add(splash);
 const bounds=new T.Box3(new T.Vector3(-site.radius,.30,-site.radius),new T.Vector3(site.radius,site.height+.5,site.radius));
