`,Ut=`// 준비 중·표시 중인 건물의 공유 그림은 보호하고 마지막 퇴출 때 해제.
export function createSharedTextureCache(){
 const cache=new Map(),entries=new Map(),groups=new WeakMap();
 return{
  has:key=>cache.has(key),get:key=>cache.get(key),
  set(key,texture){cache.set(key,texture);entries.set(texture,{key,users:0,bytes:(texture.image?.width||0)*(texture.image?.height||0)*4*(texture.generateMipmaps?4/3:1)});},
  retain(group){
   if(groups.has(group))return;const used=new Set();
   group.traverse(o=>{for(const m of o.material?Array.isArray(o.material)?o.material:[o.material]:[])if(entries.has(m.map))used.add(m.map);});
   groups.set(group,used);for(const texture of used)entries.get(texture).users++;
  },
  release(group){
   const used=groups.get(group);if(!used)return;groups.delete(group);
   for(const texture of used){const entry=entries.get(texture);if(--entry.users)continue;cache.delete(entry.key);entries.delete(texture);texture.dispose();texture.image?.close?.();}
  },
  get stats(){return{count:cache.size,bytes:[...entries.values()].reduce((total,e)=>total+e.bytes,0)};}
 };
}
