for(let i=shops.length-1;i>=0;i--)if(accessWays.some(path=>intersects(shops[i],segmentBox(path.p[0],path.p[1],path.w+2.4),1)))shops.splice(i,1);

// 남대문시장: 남대문로·퇴계로·숭례문 쪽 길·회현 쪽 끝으로 둘러싸인 큰 블록.
// 길가 가게줄 → 등을 맞댄 줄 → 좁은 뒷골목 → … 이 여러 겹 이어지고, 남은 안쪽은 시장 골목 방향 격자로 채운다.
// 같은 길·같은 구간의 점포를 한 객체로 묶어 그리기 수를 줄인다. 충돌은 점포별 회전 사각형.
const marketArea=[[-114,219],[-80,180],[-55,158],[-14,147],[-6,149],[-6,242],[-43,267],[-71,276],[-149,285]];
const insideArea=(x,z)=>{let inside=false;for(let i=0,j=marketArea.length-1;i<marketArea.length;j=i++){const a=marketArea[i],b=marketArea[j];if((a[1]>z)!==(b[1]>z)&&x<(b[0]-a[0])*(z-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;};
// 시장 안의 일반 가게는 아래 시장 줄로 대체한다.
for(let i=shops.length-1;i>=0;i--)if(shops[i].district==='market'&&insideArea(shops[i].x,shops[i].z))shops.splice(i,1);
// 랜드마크 주변의 1980년대 기준 건물. 그 자리의 일반 가게는 비운다.
// 정부종합청사(1970), 미국대사관과 쌍둥이 청사(1961), 화신백화점(1937~1987), 단성사, 충무로 극장들, 명동 코스모스·유네스코회관·옛 국립극장.
