{const book=shops.filter(b=>b.district==='jongno'&&b.z<-52).sort((a,b)=>Math.hypot(a.x-84,a.z+60)-Math.hypot(b.x-84,b.z+60))[0];if(book)Object.assign(book,{label:'종로서적',h:16,profile:'books',urbanStyle:'tile',stall:1});}
