const sinmunno={x:-168.5,z:-48,w:163,d:22.6,turn:0};
for(let i=shops.length-1;i>=0;i--)if(intersects(shops[i],sinmunno)){
 const gone=shops.splice(i,1)[0];
 for(const s of shops.filter(s=>s.row===gone.row&&Math.hypot(s.x-gone.x,s.z-gone.z)<(s.w+gone.w)/2+.3)){const side=(gone.x-s.x)*Math.cos(s.turn)-(gone.z-s.z)*Math.sin(s.turn);if(side>0)s.partyEast=false;else s.partyWest=false;}
}
