  const lot=lotAt(f.a[0]+f.ux*along+f.nx*o,f.a[1]+f.uz*along+f.nz*o,15,DEPTH*2-.2,Math.atan2(-f.nx,-f.nz),{label:name,style,h:10.4,big:true});
