 {const every=all();for(const bk of marketBlocks)bk.lots=bk.lots.filter(l=>l.big||every.some(o=>o!==l&&turnGap(l.turn,o.turn)<1&&intersects(l,o,.12)));for(let i=marketBlocks.length-1;i>=0;i--)if(!marketBlocks[i].lots.length)marketBlocks.splice(i,1);}
