export const VEHICLE_ROOF_RISE=.18;
export const TAXI_PAINTS=Object.freeze([{name:'초록 택시',hex:'#389463',weight:3,evidence:'user-art-direction'},{name:'노랑 택시',hex:'#d9b53b',weight:1,evidence:'game-approximation'}]);
